139	// Every request-shape violation is a 400 JSON error with zero writes, checked
140	// before the device even exists.
141	func TestQueryCRDTOpsHTTPRejectsBadShape(t *testing.T) {
142		h, _ := newTestHandler(t)
143		registerDevice(t, h, "dev")
144		url := "/v1/documents/doc1/crdt/query"
145	
146		send := func(contentType, raw string) *httptest.ResponseRecorder {
147			r := httptest.NewRequest(http.MethodPost, url, strings.NewReader(raw))
148			if contentType != "" {
149				r.Header.Set("Content-Type", contentType)
150			}
151			w := httptest.NewRecorder()
152			h.ServeHTTP(w, r)
153			return w
154		}
155	
156		cases := []struct {
157			name, contentType, body string
158		}{
159			{"wrong content type", "text/plain", `{"deviceId":"dev","ids":["a"]}`},
160			{"missing content type", "", `{"deviceId":"dev","ids":["a"]}`},
161			{"content type with json suffix", "application/vnd.api+json", `{"deviceId":"dev","ids":["a"]}`},
162			{"invalid json", "application/json", `{"deviceId":"dev","ids":[`},
163			{"trailing content", "application/json", `{"deviceId":"dev","ids":["a"]} junk`},
164			{"second json value", "application/json", `{"deviceId":"dev","ids":["a"]}{}`},
165			{"missing ids", "application/json", `{"deviceId":"dev"}`},
166			{"null ids", "application/json", `{"deviceId":"dev","ids":null}`},
167			{"empty ids", "application/json", `{"deviceId":"dev","ids":[]}`},
168			{"empty id element", "application/json", `{"deviceId":"dev","ids":["a",""]}`},
169			{"non-string id element", "application/json", `{"deviceId":"dev","ids":["a",1]}`},
170			{"ids not an array", "application/json", `{"deviceId":"dev","ids":"a"}`},
171			{"duplicate ids", "application/json", `{"deviceId":"dev","ids":["a","a"]}`},
172			{"missing deviceId", "application/json", `{"ids":["a"]}`},
173			{"empty deviceId", "application/json", `{"deviceId":"","ids":["a"]}`},
174			{"non-string deviceId", "application/json", `{"deviceId":7,"ids":["a"]}`},
175			{"non-object body", "application/json", `[1,2]`},
176		}
177		for _, tc := range cases {
