230	// The lookup is read-only: it commits no operation, advances no cursor and
231	// wakes neither a parked change long poll nor a CRDT push subscriber.
232	func TestQueryCRDTOpsHTTPReadOnly(t *testing.T) {
233		h, s := newTestHandler(t)
234		registerDevice(t, h, "dev")
235		w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev", crdtCounterOp("c1", 1)))
236		if w.Code != http.StatusOK {
237			t.Fatal(w.Body.String())
238		}
239		// One change-log row so the poll parks waiting for the cursor past it; the
240		// CRDT query must not wake that wait.
241		postRawChanges(t, h, "doc", "dev", `[{"id":"ch1","payload":1}]`)
242	
243		// A parked change long poll on the same document must time out despite
244		// the CRDT queries.
245		done := make(chan struct {
246			changes  int
247			timedOut bool
248			err      error
249		}, 1)
250		go func() {
251			changes, _, timedOut, err := s.WaitForChanges(t.Context(), "doc", 1, 100, 250*time.Millisecond)
252			done <- struct {
253				changes  int
254				timedOut bool
255				err      error
256			}{len(changes), timedOut, err}
257		}()
258		time.Sleep(30 * time.Millisecond) // let the poll park
259		for i := 0; i < 3; i++ {
260			if w := queryCRDTOps(t, h, "doc", `{"deviceId":"dev","ids":["c1","nope"]}`); w.Code != http.StatusOK {
261				t.Fatalf("query %d = %d %s", i, w.Code, w.Body.String())
262			}
263		}
264		got := <-done
265		if got.err != nil {
266			t.Fatalf("poll: %v", got.err)
267		}
268		if !got.timedOut || got.changes != 0 {
269			t.Fatalf("poll woken by a read-only query: %+v", got)
270		}
271	
272		// The queries wrote no operation: snapshot operation count is unchanged.
273		snap, err := s.GetCRDTSnapshot("doc")
274		if err != nil {
275			t.Fatal(err)
276		}
277		if snap.Operations != 1 {
278			t.Fatalf("query wrote operations: snapshot = %+v", snap)
279		}
280	}
