339	// After a process restart the same query yields the byte-identical body and
340	// verdicts, including found, missing and compacted answers.
341	func TestQueryCRDTOpsHTTPRestartStable(t *testing.T) {
342		dir := t.TempDir()
343		dbPath := filepath.Join(dir, "sync.db")
344	
345		st, err := app.Open(dbPath)
346		if err != nil {
347			t.Fatal(err)
348		}
349		h := NewHandler(st)
350		registerDevice(t, h, "dev-1")
351		w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev-1",
352			crdtCounterOp("a1", 5), crdtCounterOp("a2", 8)))
353		if w.Code != http.StatusOK {
354			t.Fatal(w.Body.String())
355		}
356		if w, _ := postJSON(t, h, "/v1/documents/doc/crdt/compact", map[string]any{"deviceId": "dev-1"}); w.Code != http.StatusOK {
357			t.Fatal(w.Body.String())
358		}
359		body := queryCRDTOps(t, h, "doc", `{"deviceId":"dev-1","ids":["a1","a2","nope"]}`).Body.String()
360		if err := st.Close(); err != nil {
361			t.Fatal(err)
362		}
363	
364		st2, err := app.Open(dbPath)
365		if err != nil {
366			t.Fatal(err)
367		}
368		defer func() { _ = st2.Close() }()
369		h2 := NewHandler(st2)
370		w2 := queryCRDTOps(t, h2, "doc", `{"deviceId":"dev-1","ids":["a1","a2","nope"]}`)
371		if w2.Code != http.StatusOK {
372			t.Fatalf("after restart = %d %s", w2.Code, w2.Body.String())
373		}
374		if w2.Body.String() != body {
375			t.Fatalf("body changed across restart:\nbefore %q\nafter  %q", body, w2.Body.String())
376		}
377	}
